// Clips (per-clip settings), garment library and drying sessions.
// A session with ended_at NULL is still drying; once ended it is a record ('dry' or 'early').
// 'cancel' deletes the row, so cancelled sessions leave no record.
//
// Ids are UUIDs generated by PostgreSQL; people only choose names. A physical clip is a real clip
// with a `device_id` (its ESP32's MAC), set when the device first reports (store.clipIdForDevice).
// A real 衣夾-01 without a device is created on startup, for the first clip to take over.
//
// Demo data lives in the same tables with is_demo = true (see demo.ts). Lists leave it out unless
// the caller asks for it (includeDemo), and composite foreign keys keep a session, its clip and its
// garment all real or all demo, so demo data can never end up in a real record.
import { dbClient } from '../db/client';
import { CLIP_STALE_MS, LEGACY_TOPIC, clipTopic, isUuid } from './store';
import { MATERIALS, STYLES, type Material, predictMinutes, swappedPrediction } from './prediction';

export const METHODS = ['hx711_raw', 'ads1115_raw', 'touch_raw'] as const;
export type Method = typeof METHODS[number];
export type Outcome = 'dry' | 'early' | 'cancel';

const dryingState = { schemaReady: false };
const MIN = 60000;
export const REAL_CLIP_NAME = '衣夾-01';

// Errors the caller caused; routes answer with this status instead of 503.
export class HttpError extends Error {
  constructor(public status: 400 | 404 | 409, message: string) { super(message); }
}

export const MIXED_DEMO = '衣夾和衣物必須同為真實或同為示範';

// Bun SQL puts the SQLSTATE in errno (code is a generic ERR_POSTGRES_* name).
const sqlState = (error: any): string | undefined => error?.errno ?? error?.code;
function mapConstraint(error: unknown, conflict: string): never {
  const state = sqlState(error);
  if (state === '23505') throw new HttpError(409, conflict);
  if (state === '23503') throw new HttpError(400, `參照的資料不存在，或${MIXED_DEMO}`);
  throw error;
}

// ===== Schema =====
export async function ensureDryingSchema(): Promise<void> {
  if (!dbClient.isConnected()) throw new Error('Database unavailable');
  const sql = dbClient.sql;
  await sql`
    CREATE TABLE IF NOT EXISTS clips (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 40),
      topic TEXT,
      airbox_id TEXT REFERENCES devices(device_id) ON DELETE SET NULL,
      predict_method TEXT NOT NULL DEFAULT 'hx711_raw' CHECK (predict_method IN ('hx711_raw', 'ads1115_raw', 'touch_raw')),
      is_demo BOOLEAN NOT NULL DEFAULT false,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )`;
  await sql`
    CREATE TABLE IF NOT EXISTS garments (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name TEXT NOT NULL CHECK (char_length(name) BETWEEN 1 AND 40),
      style TEXT NOT NULL CHECK (style IN ('tee', 'shirt', 'tank', 'pants', 'towel')),
      color TEXT NOT NULL CHECK (color ~ '^#[0-9A-Fa-f]{6}$'),
      material TEXT NOT NULL CHECK (material IN ('棉', '聚酯纖維', '牛仔布', '羊毛', '麻', '毛巾布')),
      is_demo BOOLEAN NOT NULL DEFAULT false,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )`;
  await sql`
    CREATE TABLE IF NOT EXISTS drying_sessions (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      clip_id UUID NOT NULL,
      garment_id UUID NOT NULL,
      started_at TIMESTAMPTZ NOT NULL,
      predicted_min INTEGER NOT NULL CHECK (predicted_min > 0),
      ended_at TIMESTAMPTZ,
      outcome TEXT CHECK (outcome IN ('dry', 'early')),
      actual_min INTEGER CHECK (actual_min >= 0),
      is_demo BOOLEAN NOT NULL DEFAULT false,
      CHECK ((ended_at IS NULL) = (outcome IS NULL)),
      CHECK (CASE WHEN outcome = 'dry' THEN actual_min IS NOT NULL ELSE actual_min IS NULL END),
      CHECK (ended_at IS NULL OR ended_at >= started_at)
    )`;
  // Columns added after the first version of these tables.
  for (const table of ['clips', 'garments', 'drying_sessions']) {
    await sql.unsafe(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS is_demo BOOLEAN NOT NULL DEFAULT false`);
  }
  await sql`ALTER TABLE clips ADD COLUMN IF NOT EXISTS topic TEXT`;
  await convertTextIds(sql);
  await ensureConstraints(sql);
  await sql`CREATE UNIQUE INDEX IF NOT EXISTS drying_sessions_active_clip_idx ON drying_sessions (clip_id) WHERE ended_at IS NULL`;
  await sql`CREATE UNIQUE INDEX IF NOT EXISTS drying_sessions_active_garment_idx ON drying_sessions (garment_id) WHERE ended_at IS NULL`;
  await sql`CREATE INDEX IF NOT EXISTS drying_sessions_garment_idx ON drying_sessions (garment_id, started_at DESC)`;
  await sql`CREATE INDEX IF NOT EXISTS drying_sessions_started_idx ON drying_sessions (started_at DESC)`;
  await sql`CREATE UNIQUE INDEX IF NOT EXISTS clips_topic_key ON clips (topic) WHERE topic IS NOT NULL`;
  // Names repeat neither among real nor among demo rows (a real and a demo row may share one).
  for (const table of ['clips', 'garments']) {
    try {
      await sql.unsafe(`CREATE UNIQUE INDEX IF NOT EXISTS ${table}_name_key ON ${table} (lower(btrim(name)), is_demo)`);
    } catch (error) {
      console.warn(`[Clothes] ${table} names repeat, unique index not created:`, (error as Error).message);
    }
  }
  await ensureRealClip(sql);
  await ensureClipReadings(sql);
  // Demo sessions carry the seed of their simulated sensor curves (web/src/utils/demoSensor.ts).
  await sql`ALTER TABLE drying_sessions ADD COLUMN IF NOT EXISTS demo_seed INTEGER`;
  await addConstraint(sql, 'drying_sessions', 'drying_sessions_demo_seed_demo_only', 'CHECK (demo_seed IS NULL OR is_demo)');
  dryingState.schemaReady = true;
}

// clips.device_id and clothes_raw.clip_id. Readings stored before clips had ids all came from the
// one clip there was, so they go to the first real clip. Runs once; later starts find nothing to fill.
async function ensureClipReadings(sql: any) {
  await sql`ALTER TABLE clips ADD COLUMN IF NOT EXISTS device_id TEXT`;
  await addConstraint(sql, 'clips', 'clips_device_id_format', "CHECK (device_id ~ '^[0-9A-F]{12}$')");
  await sql`CREATE UNIQUE INDEX IF NOT EXISTS clips_device_id_key ON clips (device_id) WHERE device_id IS NOT NULL`;
  await sql`ALTER TABLE clothes_raw ADD COLUMN IF NOT EXISTS clip_id UUID REFERENCES clips(id)`;
  const pending = await sql`SELECT 1 FROM clothes_raw WHERE clip_id IS NULL LIMIT 1`;
  if (pending.length) {
    const first = await sql`SELECT id, name FROM clips WHERE NOT is_demo ORDER BY created_at, id LIMIT 1`;
    console.log(`[Clothes] Assigning readings without a clip to ${first[0].name}; this can take a minute on a large table`);
    await sql`UPDATE clothes_raw SET clip_id = ${first[0].id}::uuid WHERE clip_id IS NULL`;
  }
  await sql`CREATE INDEX IF NOT EXISTS clothes_raw_clip_time_idx ON clothes_raw (clip_id, timestamp DESC, id DESC)`;
}

async function addConstraint(sql: any, table: string, name: string, definition: string) {
  await sql.unsafe(`DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = '${name}') THEN
      ALTER TABLE ${table} ADD CONSTRAINT ${name} ${definition};
    END IF;
  END $$`);
}

// Composite keys keep a session, its clip and its garment all real or all demo. NOT VALID on the
// name check so rows written before it never block startup (new rows are always checked).
async function ensureConstraints(sql: any) {
  await addConstraint(sql, 'clips', 'clips_id_is_demo_key', 'UNIQUE (id, is_demo)');
  await addConstraint(sql, 'garments', 'garments_id_is_demo_key', 'UNIQUE (id, is_demo)');
  await addConstraint(sql, 'drying_sessions', 'drying_sessions_clip_is_demo_fkey', 'FOREIGN KEY (clip_id, is_demo) REFERENCES clips (id, is_demo)');
  await addConstraint(sql, 'drying_sessions', 'drying_sessions_garment_is_demo_fkey', 'FOREIGN KEY (garment_id, is_demo) REFERENCES garments (id, is_demo)');
  await addConstraint(sql, 'clips', 'clips_name_trimmed', 'CHECK (name = btrim(name)) NOT VALID');
  await addConstraint(sql, 'garments', 'garments_name_trimmed', 'CHECK (name = btrim(name)) NOT VALID');
}

// Databases created before UUIDs used text ids (c1, g_xxx, demo-s1). Give every row a new UUID,
// keep every link between rows. Runs once.
async function convertTextIds(sql: any) {
  const type = await sql`
    SELECT data_type FROM information_schema.columns WHERE table_name = 'clips' AND column_name = 'id'`;
  if (type[0]?.data_type !== 'text') return;
  console.log('[Clothes] Converting clip, garment and session ids to UUIDs');
  await sql.begin(async (tx: any) => {
    await tx`CREATE TEMP TABLE clip_ids ON COMMIT DROP AS SELECT id AS old_id, gen_random_uuid()::text AS new_id FROM clips`;
    await tx`CREATE TEMP TABLE garment_ids ON COMMIT DROP AS SELECT id AS old_id, gen_random_uuid()::text AS new_id FROM garments`;
    await tx.unsafe(`DO $$ DECLARE r record; BEGIN
      FOR r IN SELECT conname FROM pg_constraint WHERE conrelid = 'drying_sessions'::regclass AND contype = 'f' LOOP
        EXECUTE format('ALTER TABLE drying_sessions DROP CONSTRAINT %I', r.conname);
      END LOOP;
    END $$`);
    await tx`UPDATE drying_sessions s SET clip_id = m.new_id FROM clip_ids m WHERE s.clip_id = m.old_id`;
    await tx`UPDATE drying_sessions s SET garment_id = m.new_id FROM garment_ids m WHERE s.garment_id = m.old_id`;
    await tx`UPDATE drying_sessions SET id = gen_random_uuid()::text`;
    await tx`UPDATE clips c SET id = m.new_id FROM clip_ids m WHERE c.id = m.old_id`;
    await tx`UPDATE garments g SET id = m.new_id FROM garment_ids m WHERE g.id = m.old_id`;
    await tx.unsafe(`ALTER TABLE clips ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid()`);
    await tx.unsafe(`ALTER TABLE garments ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid()`);
    await tx.unsafe(`ALTER TABLE drying_sessions
      ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid(),
      ALTER COLUMN clip_id TYPE uuid USING clip_id::uuid,
      ALTER COLUMN garment_id TYPE uuid USING garment_id::uuid`);
  });
}

// There is always at least one real clip: a fresh database gets 衣夾-01, waiting for its device.
async function ensureRealClip(sql: any) {
  const real = await sql`SELECT 1 FROM clips WHERE NOT is_demo LIMIT 1`;
  if (!real.length) await sql`INSERT INTO clips (name) VALUES (${REAL_CLIP_NAME})`;
}

function database() {
  if (!dbClient.isConnected() || !dryingState.schemaReady) throw new Error('Drying database unavailable');
  return dbClient.sql;
}

// Path ids that are not UUIDs cannot exist; answer 404 instead of letting PostgreSQL fail.
function checkId(id: string, what: string) {
  if (!isUuid(id)) throw new HttpError(404, `找不到這${what}`);
}

// Names repeat neither among real nor among demo rows (case and surrounding spaces ignored).
async function assertNameFree(tx: any, table: 'clips' | 'garments', name: string, isDemo: boolean, exceptId: string | null = null) {
  const rows = table === 'clips'
    ? await tx`SELECT 1 FROM clips WHERE lower(name) = lower(${name}) AND is_demo = ${isDemo} AND id IS DISTINCT FROM ${exceptId}::uuid`
    : await tx`SELECT 1 FROM garments WHERE lower(name) = lower(${name}) AND is_demo = ${isDemo} AND id IS DISTINCT FROM ${exceptId}::uuid`;
  if (rows.length) throw new HttpError(409, `已經有名為「${name}」的${table === 'clips' ? '衣夾' : '衣物'}`);
}

// ===== Body validation (pure; also used by tests) =====
export interface GarmentDraft { name: string; style: string; color: string; material: Material }

// ?demo=include adds demo rows; without it lists hold real data only. undefined = bad value.
export function parseDemoQuery(value: string | undefined): boolean | undefined {
  if (value === undefined) return false;
  return value === 'include' ? true : undefined;
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

function checkKeys(body: Record<string, unknown>, allowed: string[]) {
  const extra = Object.keys(body).filter((key) => !allowed.includes(key));
  if (extra.length) throw new HttpError(400, `不支援的欄位：${extra.join(', ')}`);
}

// Clip and garment names: 1–40 characters after trimming (they are stored trimmed).
export const validName = (v: unknown) => typeof v === 'string' && v.trim().length >= 1 && v.trim().length <= 40;

const GARMENT_FIELDS: Record<string, (value: unknown) => boolean> = {
  name: validName,
  style: (v) => (STYLES as readonly unknown[]).includes(v),
  color: (v) => typeof v === 'string' && /^#[0-9A-Fa-f]{6}$/.test(v),
  material: (v) => (MATERIALS as readonly unknown[]).includes(v),
};

// partial: PATCH (any subset, at least one); otherwise all four fields are required.
export function parseGarment(body: unknown, partial = false): Partial<GarmentDraft> {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  checkKeys(body, Object.keys(GARMENT_FIELDS));
  const out: Record<string, unknown> = {};
  for (const [key, valid] of Object.entries(GARMENT_FIELDS)) {
    if (body[key] === undefined) {
      if (!partial) throw new HttpError(400, `缺少欄位 ${key}`);
      continue;
    }
    if (!valid(body[key])) throw new HttpError(400, `欄位 ${key} 格式錯誤`);
    out[key] = key === 'name' ? (body[key] as string).trim() : body[key];
  }
  if (partial && !Object.keys(out).length) throw new HttpError(400, '沒有要更新的欄位');
  return out as Partial<GarmentDraft>;
}

// POST /garments: the garment fields plus an optional is_demo (default false).
export function parseNewGarment(body: unknown): { draft: GarmentDraft; isDemo: boolean } {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  const { is_demo: isDemo = false, ...rest } = body;
  if (typeof isDemo !== 'boolean') throw new HttpError(400, '欄位 is_demo 格式錯誤');
  return { draft: parseGarment(rest) as GarmentDraft, isDemo };
}

export interface ClipPatch { name?: string; airbox_id?: string | null; predict_method?: Method }
const AIRBOX_ID = /^[A-Za-z0-9_.:-]{1,64}$/;
export function parseClipPatch(body: unknown): ClipPatch {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  checkKeys(body, ['name', 'airbox_id', 'predict_method']);
  const out: ClipPatch = {};
  if (body.name !== undefined) {
    if (!validName(body.name)) throw new HttpError(400, '欄位 name 格式錯誤');
    out.name = (body.name as string).trim();
  }
  if (body.airbox_id !== undefined) {
    if (body.airbox_id !== null && !(typeof body.airbox_id === 'string' && AIRBOX_ID.test(body.airbox_id))) {
      throw new HttpError(400, '欄位 airbox_id 格式錯誤');
    }
    out.airbox_id = body.airbox_id as string | null;
  }
  if (body.predict_method !== undefined) {
    if (!(METHODS as readonly unknown[]).includes(body.predict_method)) throw new HttpError(400, '欄位 predict_method 格式錯誤');
    out.predict_method = body.predict_method as Method;
  }
  if (!Object.keys(out).length) throw new HttpError(400, '沒有要更新的欄位');
  return out;
}

// demo (demo clips only): the seed of the simulated curves, and how long ago to start the session so
// that the garment is already as dry as the person chose (the page works that out from the seed).
export interface DemoStart { seed: number; elapsed_min: number }
export type StartBody = ({ clip_id: string; garment_id: string } | { clip_id: string; garment: GarmentDraft }) & { demo?: DemoStart };
export function parseStart(body: unknown): StartBody {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  checkKeys(body, ['clip_id', 'garment_id', 'garment', 'demo']);
  if (!isUuid(body.clip_id)) throw new HttpError(400, '欄位 clip_id 必須是衣夾的 UUID');
  let demo: DemoStart | undefined;
  if (body.demo !== undefined) {
    const d = body.demo as Record<string, unknown>;
    if (!isObject(d) || Object.keys(d).some((k) => k !== 'seed' && k !== 'elapsed_min') ||
        !Number.isInteger(d.seed) || (d.seed as number) < 0 || (d.seed as number) > 2147483647 ||
        !Number.isInteger(d.elapsed_min) || (d.elapsed_min as number) < 0 || (d.elapsed_min as number) > 7 * 1440) {
      throw new HttpError(400, '欄位 demo 必須是 { seed: 0～2147483647, elapsed_min: 0～10080 }');
    }
    demo = { seed: d.seed as number, elapsed_min: d.elapsed_min as number };
  }
  const withDemo = <T extends object>(start: T) => (demo ? { ...start, demo } : start);
  if ((body.garment_id === undefined) === (body.garment === undefined)) {
    throw new HttpError(400, 'garment_id 與 garment 必須擇一提供');
  }
  if (body.garment_id !== undefined) {
    if (!isUuid(body.garment_id)) throw new HttpError(400, '欄位 garment_id 必須是衣物的 UUID');
    return withDemo({ clip_id: body.clip_id, garment_id: body.garment_id });
  }
  return withDemo({ clip_id: body.clip_id, garment: parseGarment(body.garment) as GarmentDraft });
}

export function parseGarmentId(body: unknown): string {
  if (!isObject(body) || !isUuid(body.garment_id)) throw new HttpError(400, '欄位 garment_id 必須是衣物的 UUID');
  return body.garment_id;
}

// PATCH /sessions/:id on an ended record: move it to another garment and/or correct its times.
// The longest record that can be set is RECORD_MAX_MS (the time editor shows at most two days).
export const RECORD_MAX_MS = 48 * 60 * MIN;
export interface RecordPatch { garment_id?: string; started_at?: Date; ended_at?: Date }
export function parseRecordPatch(body: unknown): RecordPatch {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  checkKeys(body, ['garment_id', 'started_at', 'ended_at']);
  const out: RecordPatch = {};
  if (body.garment_id !== undefined) {
    if (!isUuid(body.garment_id)) throw new HttpError(400, '欄位 garment_id 必須是衣物的 UUID');
    out.garment_id = body.garment_id;
  }
  for (const key of ['started_at', 'ended_at'] as const) {
    if (body[key] === undefined) continue;
    const date = typeof body[key] === 'string' ? new Date(body[key] as string) : new Date(NaN);
    if (!Number.isFinite(date.getTime())) throw new HttpError(400, `欄位 ${key} 時間格式錯誤`);
    out[key] = date;
  }
  if (!Object.keys(out).length) throw new HttpError(400, '沒有要更新的欄位');
  if (out.started_at && out.ended_at) checkRecordTimes(out.started_at, out.ended_at);
  return out;
}

export function checkRecordTimes(start: Date, end: Date, now?: Date) {
  if (start >= end) throw new HttpError(400, '結束需晚於開始');
  if (end.getTime() - start.getTime() > RECORD_MAX_MS) throw new HttpError(400, '一筆紀錄最長 48 小時');
  if (now && end > now) throw new HttpError(400, '結束時間不能晚於現在');
}

export function parseOutcome(body: unknown): Outcome {
  if (!isObject(body)) throw new HttpError(400, '內容必須是 JSON 物件');
  checkKeys(body, ['outcome']);
  if (body.outcome !== 'dry' && body.outcome !== 'early' && body.outcome !== 'cancel') {
    throw new HttpError(400, 'outcome 必須是 dry、early 或 cancel');
  }
  return body.outcome;
}

// ===== Row shapes =====
type SessionRow = {
  id: string; clip_id: string; garment_id: string; started_at: Date; predicted_min: number;
  ended_at: Date | null; outcome: 'dry' | 'early' | null; actual_min: number | null; is_demo: boolean; demo_seed: number | null;
  g_name: string; g_style: string; g_color: string; g_material: string;
};

function sessionOut(row: SessionRow) {
  const started = new Date(row.started_at);
  return {
    id: row.id, clip_id: row.clip_id, garment_id: row.garment_id, started_at: started,
    predicted_min: row.predicted_min, dry_at: new Date(started.getTime() + row.predicted_min * MIN),
    ended_at: row.ended_at, outcome: row.outcome, actual_min: row.actual_min, is_demo: row.is_demo, demo_seed: row.demo_seed ?? null,
    garment: { id: row.garment_id, name: row.g_name, style: row.g_style, color: row.g_color, material: row.g_material },
  };
}

// Sessions joined with their garment; `where` picks the active ones or one by id.
async function selectSessions(sql: any, where: 'active' | 'id', id?: string, includeDemo = false) {
  const rows: SessionRow[] = where === 'active'
    ? await sql`
      SELECT s.id, s.clip_id, s.garment_id, s.started_at, s.predicted_min, s.ended_at, s.outcome, s.actual_min, s.is_demo, s.demo_seed,
        g.name AS g_name, g.style AS g_style, g.color AS g_color, g.material AS g_material
      FROM drying_sessions s JOIN garments g ON g.id = s.garment_id
      WHERE s.ended_at IS NULL AND (${includeDemo} OR NOT s.is_demo) ORDER BY s.started_at`
    : await sql`
      SELECT s.id, s.clip_id, s.garment_id, s.started_at, s.predicted_min, s.ended_at, s.outcome, s.actual_min, s.is_demo, s.demo_seed,
        g.name AS g_name, g.style AS g_style, g.color AS g_color, g.material AS g_material
      FROM drying_sessions s JOIN garments g ON g.id = s.garment_id
      WHERE s.id = ${id}::uuid`;
  return rows.map(sessionOut);
}

async function predictFor(sql: any, garmentId: string, material: Material) {
  const rows = await sql`
    SELECT actual_min FROM drying_sessions WHERE garment_id = ${garmentId}::uuid AND outcome = 'dry'`;
  return predictMinutes(material, rows.map((row: { actual_min: number }) => row.actual_min));
}

// ===== Clips =====
export async function listClips(includeDemo = false) {
  const sql = database();
  const clips = await sql`
    SELECT c.id, c.name, c.device_id, c.airbox_id, c.predict_method, c.is_demo, c.created_at, c.updated_at,
      (SELECT r.id FROM clothes_raw r WHERE r.clip_id = c.id ORDER BY r.timestamp DESC, r.id DESC LIMIT 1) AS last_id
    FROM clips c WHERE ${includeDemo} OR NOT c.is_demo ORDER BY c.is_demo, lower(c.name)`;
  const firstReal = clips.find((clip: any) => !clip.is_demo && !clip.device_id)?.id;
  // Each clip's newest reading, for the device cards.
  const lastIds = clips.map((clip: any) => clip.last_id).filter((id: unknown) => id != null);
  const lastRows = lastIds.length
    ? await sql`SELECT id, timestamp, hx711_raw, ads1115_raw, touch_raw FROM clothes_raw WHERE id IN ${sql(lastIds)}` : [];
  const active = await selectSessions(sql, 'active', undefined, includeDemo);
  // Divider settings for converting the ADS1115 reading to ohms (resistance.ts); none on a fresh clip.
  const dividers = await sql`SELECT id, clip_id, since, divider_ohm, open_count FROM clip_dividers ORDER BY since`.catch(() => []);
  // HX711 calibration for showing the weight in grams (weight.ts); none on a fresh clip.
  const scales = await sql`SELECT id, clip_id, since, tare_count, counts_per_gram FROM clip_scales ORDER BY since`.catch(() => []);
  const now = Date.now();
  return clips.map((clip: any) => {
    // Demo clips never report; the front end simulates their state.
    const { last_id: lastId, ...rest } = clip;
    const last = clip.is_demo ? null : lastRows.find((row: any) => String(row.id) === String(lastId)) ?? null;
    const lastReading = last?.timestamp ?? null;
    return {
      ...rest,
      dividers: dividers.filter((d: any) => d.clip_id === clip.id)
        .map((d: any) => ({ id: d.id, since: d.since, divider_ohm: d.divider_ohm, open_count: d.open_count })),
      scales: scales.filter((s: any) => s.clip_id === clip.id)
        .map((s: any) => ({ id: s.id, since: s.since, tare_count: s.tare_count, counts_per_gram: Number(s.counts_per_gram) })),
      latest: last && { timestamp: last.timestamp, hx711_raw: last.hx711_raw, ads1115_raw: last.ads1115_raw, touch_raw: last.touch_raw },
      // Where the clip publishes: its own topic, or the shared one of firmware before 0.5.0.
      topic: clip.device_id ? clipTopic(clip.device_id, 'raw') : clip.id === firstReal ? LEGACY_TOPIC : null,
      last_reading: lastReading,
      online: lastReading !== null && now - new Date(lastReading).getTime() <= CLIP_STALE_MS,
      session: active.find((session) => session.clip_id === clip.id) ?? null,
    };
  });
}

export async function updateClip(id: string, patch: ClipPatch) {
  checkId(id, '支衣夾');
  const sql = database();
  try {
    return await sql.begin(async (tx: any) => {
      const rows = await tx`SELECT name, airbox_id, predict_method, is_demo FROM clips WHERE id = ${id}::uuid FOR UPDATE`;
      if (!rows.length) throw new HttpError(404, '找不到這支衣夾');
      if (patch.airbox_id) {
        const box = await tx`SELECT 1 FROM devices WHERE device_id = ${patch.airbox_id}`;
        if (!box.length) throw new HttpError(400, '找不到這個空氣盒子');
      }
      if (patch.name !== undefined) await assertNameFree(tx, 'clips', patch.name, rows[0].is_demo, id);
      const next = { ...rows[0], ...patch };
      const updated = await tx`
        UPDATE clips SET name = ${next.name}, airbox_id = ${next.airbox_id}, predict_method = ${next.predict_method}, updated_at = now()
        WHERE id = ${id}::uuid
        RETURNING id, name, device_id, airbox_id, predict_method, is_demo, created_at, updated_at`;
      return updated[0];
    });
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, `已經有名為「${patch.name}」的衣夾`);
  }
}

// Only demo clips can be removed; their demo sessions go with them.
export async function deleteClip(id: string) {
  checkId(id, '支衣夾');
  const sql = database();
  await sql.begin(async (tx: any) => {
    const rows = await tx`SELECT is_demo FROM clips WHERE id = ${id}::uuid FOR UPDATE`;
    if (!rows.length) throw new HttpError(404, '找不到這支衣夾');
    if (!rows[0].is_demo) throw new HttpError(400, '實際的衣夾不能移除');
    await tx`DELETE FROM drying_sessions WHERE clip_id = ${id}::uuid AND is_demo`;
    await tx`DELETE FROM clips WHERE id = ${id}::uuid`;
  });
}

// ===== Garments =====
export async function listGarments(includeDemo = false) {
  return database()`
    SELECT g.id, g.name, g.style, g.color, g.material, g.is_demo, g.created_at, g.updated_at,
      (SELECT count(*)::int FROM drying_sessions s WHERE s.garment_id = g.id AND s.outcome = 'dry') AS dry_count,
      (SELECT count(*)::int FROM drying_sessions s WHERE s.garment_id = g.id) AS session_count,
      EXISTS (SELECT 1 FROM drying_sessions s WHERE s.garment_id = g.id AND s.ended_at IS NULL) AS busy
    FROM garments g WHERE ${includeDemo} OR NOT g.is_demo ORDER BY g.is_demo, g.created_at, g.id`;
}

async function insertGarment(tx: any, draft: GarmentDraft, isDemo: boolean) {
  await assertNameFree(tx, 'garments', draft.name, isDemo);
  const rows = await tx`
    INSERT INTO garments (name, style, color, material, is_demo)
    VALUES (${draft.name}, ${draft.style}, ${draft.color}, ${draft.material}, ${isDemo})
    RETURNING id, name, style, color, material, is_demo, created_at, updated_at`;
  return rows[0];
}

export async function createGarment(draft: GarmentDraft, isDemo = false) {
  try {
    const garment = await database().begin((tx: any) => insertGarment(tx, draft, isDemo));
    return { ...garment, dry_count: 0, session_count: 0, busy: false };
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, `已經有名為「${draft.name}」的衣物`);
  }
}

export async function updateGarment(id: string, patch: Partial<GarmentDraft>) {
  checkId(id, '件衣物');
  const sql = database();
  try {
    return await sql.begin(async (tx: any) => {
      const rows = await tx`SELECT name, style, color, material, is_demo FROM garments WHERE id = ${id}::uuid FOR UPDATE`;
      if (!rows.length) throw new HttpError(404, '找不到這件衣物');
      if (patch.name !== undefined) await assertNameFree(tx, 'garments', patch.name, rows[0].is_demo, id);
      const next = { ...rows[0], ...patch };
      const updated = await tx`
        UPDATE garments SET name = ${next.name}, style = ${next.style}, color = ${next.color}, material = ${next.material}, updated_at = now()
        WHERE id = ${id}::uuid
        RETURNING id, name, style, color, material, is_demo, created_at, updated_at`;
      return updated[0];
    });
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, `已經有名為「${patch.name}」的衣物`);
  }
}

// A garment with any session (drying or ended) cannot be removed: delete those records or move
// them to another garment first, so no record ever loses its garment.
export async function deleteGarment(id: string) {
  checkId(id, '件衣物');
  const sql = database();
  await sql.begin(async (tx: any) => {
    const rows = await tx`SELECT 1 FROM garments WHERE id = ${id}::uuid FOR UPDATE`;
    if (!rows.length) throw new HttpError(404, '找不到這件衣物');
    const used = await tx`SELECT count(*)::int AS n FROM drying_sessions WHERE garment_id = ${id}::uuid`;
    if (used[0].n) throw new HttpError(409, `這件衣物還有 ${used[0].n} 筆晾衣紀錄，請先刪除或移到其他衣物`);
    await tx`DELETE FROM garments WHERE id = ${id}::uuid`;
  });
}

// ===== Sessions =====
export async function listActiveSessions(includeDemo = false) {
  return selectSessions(database(), 'active', undefined, includeDemo);
}

export async function startSession(body: StartBody, now: Date) {
  const sql = database();
  try {
    const id = await sql.begin(async (tx: any) => {
      const clip = (await tx`SELECT is_demo FROM clips WHERE id = ${body.clip_id}::uuid`)[0];
      if (!clip) throw new HttpError(404, '找不到這支衣夾');
      // A new garment is created real or demo to match the clip.
      const garment = 'garment' in body
        ? await insertGarment(tx, body.garment, clip.is_demo)
        : (await tx`SELECT id, material, is_demo FROM garments WHERE id = ${body.garment_id}::uuid`)[0];
      if (!garment) throw new HttpError(404, '找不到這件衣物');
      if (garment.is_demo !== clip.is_demo) throw new HttpError(400, MIXED_DEMO);
      if (body.demo && !clip.is_demo) throw new HttpError(400, '只有示範衣夾可以設定示範的乾燥程度');
      const predicted = await predictFor(tx, garment.id, garment.material);
      // A demo session always has a seed for its simulated curves; it may start in the past.
      const seed = clip.is_demo ? body.demo?.seed ?? Math.floor(Math.random() * 2147483647) : null;
      const startedAt = new Date(now.getTime() - (body.demo?.elapsed_min ?? 0) * MIN);
      const rows = await tx`
        INSERT INTO drying_sessions (clip_id, garment_id, started_at, predicted_min, is_demo, demo_seed)
        VALUES (${body.clip_id}::uuid, ${garment.id}::uuid, ${startedAt}, ${predicted}, ${clip.is_demo}, ${seed})
        RETURNING id`;
      return rows[0].id;
    });
    return (await selectSessions(sql, 'id', id))[0];
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, '這支衣夾或這件衣物已經在晾衣中');
  }
}

export async function swapGarment(sessionId: string, garmentId: string, now: Date) {
  checkId(sessionId, '筆晾衣');
  const sql = database();
  try {
    await sql.begin(async (tx: any) => {
      const rows = await tx`SELECT started_at, garment_id, ended_at, is_demo FROM drying_sessions WHERE id = ${sessionId}::uuid FOR UPDATE`;
      if (!rows.length) throw new HttpError(404, '找不到這筆晾衣');
      if (rows[0].ended_at) throw new HttpError(409, '這筆晾衣已經結束');
      // The same garment still re-predicts: its material may just have been edited.
      const garment = (await tx`SELECT id, material, is_demo FROM garments WHERE id = ${garmentId}::uuid`)[0];
      if (!garment) throw new HttpError(404, '找不到這件衣物');
      if (garment.is_demo !== rows[0].is_demo) throw new HttpError(400, MIXED_DEMO);
      const elapsed = (now.getTime() - new Date(rows[0].started_at).getTime()) / MIN;
      const predicted = swappedPrediction(elapsed, await predictFor(tx, garment.id, garment.material));
      await tx`UPDATE drying_sessions SET garment_id = ${garmentId}::uuid, predicted_min = ${predicted} WHERE id = ${sessionId}::uuid`;
    });
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, '這件衣物已經在其他衣夾上晾');
  }
  return (await selectSessions(sql, 'id', sessionId))[0];
}

export async function endSession(sessionId: string, outcome: Outcome, now: Date) {
  checkId(sessionId, '筆晾衣');
  const sql = database();
  return sql.begin(async (tx: any) => {
    const rows = await tx`SELECT started_at, ended_at FROM drying_sessions WHERE id = ${sessionId}::uuid FOR UPDATE`;
    if (!rows.length) throw new HttpError(404, '找不到這筆晾衣');
    if (rows[0].ended_at) throw new HttpError(409, '這筆晾衣已經結束');
    if (outcome === 'cancel') {
      await tx`DELETE FROM drying_sessions WHERE id = ${sessionId}::uuid`;
      return null;
    }
    const startedAt = new Date(rows[0].started_at);
    // Never before started_at, even if the clock moved.
    const endedAt = now < startedAt ? startedAt : now;
    const actual = outcome === 'dry' ? Math.round((endedAt.getTime() - startedAt.getTime()) / MIN) : null;
    await tx`UPDATE drying_sessions SET ended_at = ${endedAt}, outcome = ${outcome}, actual_min = ${actual} WHERE id = ${sessionId}::uuid`;
    return (await selectSessions(tx, 'id', sessionId))[0];
  });
}

// Ended sessions that started in [start, end], newest first, and how many there are in total.
export async function listRecords(start: Date | null, end: Date | null, limit: number, includeDemo = false) {
  const sql = database();
  const from = start ?? new Date(0);
  const to = end ?? new Date('9999-12-31T00:00:00Z');
  const rows: SessionRow[] = await sql`
    SELECT s.id, s.clip_id, s.garment_id, s.started_at, s.predicted_min, s.ended_at, s.outcome, s.actual_min, s.is_demo, s.demo_seed,
      g.name AS g_name, g.style AS g_style, g.color AS g_color, g.material AS g_material
    FROM drying_sessions s JOIN garments g ON g.id = s.garment_id
    WHERE s.ended_at IS NOT NULL AND s.started_at >= ${from} AND s.started_at <= ${to} AND (${includeDemo} OR NOT s.is_demo)
    ORDER BY s.started_at DESC, s.id DESC LIMIT ${limit}`;
  const total = await sql`
    SELECT count(*)::int AS total FROM drying_sessions
    WHERE ended_at IS NOT NULL AND started_at >= ${from} AND started_at <= ${to} AND (${includeDemo} OR NOT is_demo)`;
  return { records: rows.map(sessionOut), total: total[0].total as number };
}

// One session (drying or ended) with its garment.
export async function getSession(id: string) {
  checkId(id, '筆晾衣');
  const session = (await selectSessions(database(), 'id', id))[0];
  if (!session) throw new HttpError(404, '找不到這筆晾衣');
  return session;
}

// Corrects an ended record. The prediction made at the time is kept; a 'dry' record's
// actual minutes follow the new times. Drying sessions change garment via swapGarment.
export async function updateRecord(id: string, patch: RecordPatch, now: Date) {
  checkId(id, '筆晾衣');
  const sql = database();
  try {
    await sql.begin(async (tx: any) => {
      const rows = await tx`SELECT started_at, ended_at, outcome, is_demo FROM drying_sessions WHERE id = ${id}::uuid FOR UPDATE`;
      if (!rows.length) throw new HttpError(404, '找不到這筆晾衣');
      const row = rows[0];
      if (!row.ended_at) throw new HttpError(409, '這筆晾衣還沒結束，請在晾衣中更換衣物');
      if (patch.garment_id) {
        const garment = (await tx`SELECT is_demo FROM garments WHERE id = ${patch.garment_id}::uuid`)[0];
        if (!garment) throw new HttpError(404, '找不到這件衣物');
        if (garment.is_demo !== row.is_demo) throw new HttpError(400, MIXED_DEMO);
        await tx`UPDATE drying_sessions SET garment_id = ${patch.garment_id}::uuid WHERE id = ${id}::uuid`;
      }
      if (patch.started_at || patch.ended_at) {
        const start = patch.started_at ?? new Date(row.started_at);
        const end = patch.ended_at ?? new Date(row.ended_at);
        checkRecordTimes(start, end, now);
        const actual = row.outcome === 'dry' ? Math.round((end.getTime() - start.getTime()) / MIN) : null;
        await tx`UPDATE drying_sessions SET started_at = ${start}, ended_at = ${end}, actual_min = ${actual} WHERE id = ${id}::uuid`;
      }
    });
  } catch (error) {
    if (error instanceof HttpError) throw error;
    mapConstraint(error, '這筆紀錄無法更新');
  }
  return getSession(id);
}

// Removes an ended record. A drying session is ended with 'cancel' instead.
export async function deleteRecord(id: string) {
  checkId(id, '筆晾衣');
  const sql = database();
  await sql.begin(async (tx: any) => {
    const rows = await tx`SELECT ended_at FROM drying_sessions WHERE id = ${id}::uuid FOR UPDATE`;
    if (!rows.length) throw new HttpError(404, '找不到這筆晾衣');
    if (!rows[0].ended_at) throw new HttpError(409, '這筆晾衣還沒結束，請用「取消晾衣」');
    await tx`DELETE FROM drying_sessions WHERE id = ${id}::uuid`;
  });
}
